5.query:
timeseries a0 = avg(aerospike_sindex_stat_gc_recs, filter: { cluster_name == $cluster and ns == $namespace and sindex == $sindex }), by: { cluster_name, service }
| fieldsAdd a0 = arrayDelta(a0)
| fieldsAdd value = a0[]
| fieldsRemove a0
| summarize value = sum(value[]), by: { timeframe, interval }
